import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void inheritedVehicleAndCargoFailures(){Object t=TaskBinding.truck(2,10,25,100);assertEquals(250,TaskBinding.range(t));assertEquals(2,TaskBinding.fuel(t,50),1e-6);assertThrows(IllegalArgumentException.class,()->TaskBinding.setFuel(t,0));assertEquals(250,TaskBinding.range(t));assertThrows(IllegalArgumentException.class,()->TaskBinding.fuel(t,-1));assertThrows(IllegalArgumentException.class,()->TaskBinding.cargo(t,-1));assertEquals(100,TaskBinding.cargo(t));assertThrows(IllegalArgumentException.class,()->TaskBinding.truck(2,10,25,-1));}}
